"""docs/EGG_TASKS.md from food/egg_tasks.TASKS (+ register sources) and the crack/boil studies."""
import json
import os
import sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)
from food import params as PR  # noqa: E402
from food.egg_tasks import TASKS  # noqa: E402

L = ["# Egg kitchen tasks as action designators", "",
     "Generated by `tools/egg_tasks_doc.py` from `food/egg_tasks.py`. The task knowledge was researched on cooking sites "
     "(America's Test Kitchen, egg boards, Milk Street, Food Network, USDA/CDC; wikiHow and Serious Eats only via "
     "snippets because they block automated access). Parameters marked by a twin model are computed per egg instance: "
     "strike speed by `food/egg_crack.py` (study: `tools/egg_crack_study.py`), boil time by `food/egg_cook.py` "
     "(`food.egg_tasks.best_boil_time`).", ""]
crack = json.load(open(os.path.join(ROOT, "test_reports", "egg_crack_study.json")))["summary"]
L += ["## Twin answers", "", "| strike surface | best speed | P(ready for frying) with half-shell recovery | 90 % window |",
      "|---|---|---|---|"]
for k, v in crack.items():
    L.append(f"| {k} | {v['v_best']:.2f} m/s | {v['p_best_recovery']:.0%} | {v['window_90pct'][0]:.2f}-{v['window_90pct'][1]:.2f} m/s |")
L += [""]
for name, d in TASKS.items():
    L += [f"## {name}", "", f"**Goal:** {d['goal']}", "", "**Parameters**", ""]
    for p, v in d["params"].items():
        L.append(f"- `{p}`: {v[0]}" + (f" (default {v[1]})" if v[1] is not None else "") + (f" — {v[2]}" if v[2] else ""))
    L += ["", "**Steps**", ""] + [f"{i + 1}. {s}" for i, s in enumerate(d["steps"])]
    L += ["", f"**Preconditions:** {'; '.join(d['pre'])}", "", f"**Effects:** {'; '.join(d['effects'])}", "",
          "| failure | cue | recovery |", "|---|---|---|"]
    for f, (cue, rec) in d["failures"].items():
        L.append(f"| {f} | {cue} | {rec} |")
    L += ["", f"**Twin model:** {d['model']}", "", "**Sources:** " + "; ".join(
        f"{s} ({PR.SOURCES.get(s, '?')})" for s in d["sources"]), ""]
open(os.path.join(ROOT, "docs", "EGG_TASKS.md"), "w").write("\n".join(L))
print("wrote docs/EGG_TASKS.md")
